class ContractProgress { final String id,title,description; final int target,reward; int progress=0; bool claimed=false; ContractProgress(this.id,this.title,this.description,this.target,this.reward); bool get completed=>progress>=target; void addProgress([int amount=1]){if(!claimed)progress=(progress+amount).clamp(0,target);} Map<String,dynamic> toJson()=>{'id':id,'progress':progress,'claimed':claimed}; }
class ContractBoard { final List<ContractProgress> contracts=[ContractProgress('purge','Зачистка','Уничтожить противников',20,25),ContractProgress('relics','Археолог','Найти тайники или реликвии',3,35),ContractProgress('elite','Приоритетная цель','Победить элитных противников',4,45)]; void recordKill({bool elite=false}){contracts.firstWhere((e)=>e.id=='purge').addProgress();if(elite)contracts.firstWhere((e)=>e.id=='elite').addProgress();} void recordCache()=>contracts.firstWhere((e)=>e.id=='relics').addProgress(); Map<String,dynamic> toJson()=>{'contracts':contracts.map((e)=>e.toJson()).toList()}; void loadJson(dynamic raw){if(raw is! Map||raw['contracts'] is! List)return;for(final item in raw['contracts']){if(item is! Map)continue;for(final c in contracts){if(c.id==item['id']){c.progress=(item['progress'] as num?)?.toInt()??0;c.claimed=item['claimed']==true;}}}} }
